Write tests for this legacy loader. Don't change the production code.

```swift
final class WeatherLoader: @unchecked Sendable {
    private let session: URLSession
    init(session: URLSession = .shared) { self.session = session }

    func load(city: String, completion: @escaping @Sendable (Result<Forecast, Error>) -> Void) {
        let url = URL(string: "https://api.example.com/forecast?city=\(city)")!
        session.dataTask(with: url) { data, _, error in
            if let error { return completion(.failure(error)) }
            do { completion(.success(try JSONDecoder().decode(Forecast.self, from: data ?? Data()))) }
            catch { completion(.failure(error)) }
        }.resume()
    }
}

struct Forecast: Decodable, Equatable { let city: String; let highC: Int }
```

